// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title GuardMeshAudit
 * @notice Immutable decision ledger for the GuardMesh decentralized AI firewall.
 *         Deployed on 0G Chain (EVM-compatible, Cancun-Deneb).
 *
 * @dev Records the merkle root hash of every decision bundle written to
 *      0G Storage (intent payload + guardian verdicts + consensus outcome).
 *      Anyone can verify any decision by querying its merkle root.
 *      The full event blob lives in 0G Storage; this contract is the
 *      tamper-proof index and receipt layer — the on-chain proof that
 *      a decision happened and what its outcome was.
 */
contract GuardMeshAudit {

    // ─────────────────────────────────────────────────────────────────────────
    // Data Structures
    // ─────────────────────────────────────────────────────────────────────────

    /// @notice Outcome codes for dashboard colour-coding.
    uint8 public constant OUTCOME_APPROVED  = 1;
    uint8 public constant OUTCOME_BLOCKED   = 2;
    uint8 public constant OUTCOME_CONTESTED = 3; // majority approved, one blocked
    uint8 public constant OUTCOME_PENDING   = 4; // human review required

    struct Decision {
        string   agentId;           // e.g. "eng-assistant-04"
        bytes32  merkleRoot;        // root of (intent + verdicts) stored in 0G Storage
        bool     approved;          // final consensus result
        uint8    outcome;           // OUTCOME_* constant for UI
        string   actionType;        // e.g. "forum_post", "change_permissions"
        string   target;            // e.g. "internal-engineering-forum"
        uint8    approveCount;      // how many guardians approved (0-3)
        uint8    blockCount;        // how many guardians blocked  (0-3)
        string   blockedReason;     // aggregated reason if blocked/contested
        uint256  intentTimestamp;   // when the intent was originally broadcast (off-chain time)
        uint256  recordedAt;        // block.timestamp when anchored on-chain
        address  recorder;          // consensus engine address that submitted
    }

    // ─────────────────────────────────────────────────────────────────────────
    // State
    // ─────────────────────────────────────────────────────────────────────────

    /// merkleRoot → Decision
    mapping(bytes32 => Decision) private _decisions;

    /// agentId hash → ordered list of merkle roots (chronological)
    mapping(bytes32 => bytes32[]) private _agentHistory;

    /// flat global list of all merkle roots (for pagination)
    bytes32[] private _allRoots;

    /// Addresses authorised to call recordDecision (the consensus engines)
    mapping(address => bool) public authorizedRecorders;

    /// Contract admin (deployer by default, transferable)
    address public admin;

    // ─────────────────────────────────────────────────────────────────────────
    // Events
    // ─────────────────────────────────────────────────────────────────────────

    event DecisionRecorded(
        string  indexed agentId,
        bytes32 indexed merkleRoot,
        bool            approved,
        uint8           outcome,
        string          actionType,
        uint256         intentTimestamp,
        address         recorder
    );

    event RecorderAuthorized(address indexed recorder, uint256 timestamp);
    event RecorderRevoked   (address indexed recorder, uint256 timestamp);
    event AdminTransferred  (address indexed oldAdmin,  address indexed newAdmin);

    // ─────────────────────────────────────────────────────────────────────────
    // Modifiers
    // ─────────────────────────────────────────────────────────────────────────

    modifier onlyAdmin() {
        require(msg.sender == admin, "GuardMesh: Not admin");
        _;
    }

    modifier onlyAuthorized() {
        require(
            authorizedRecorders[msg.sender] || msg.sender == admin,
            "GuardMesh: Not authorized recorder"
        );
        _;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Constructor
    // ─────────────────────────────────────────────────────────────────────────

    constructor() {
        admin = msg.sender;
        authorizedRecorders[msg.sender] = true;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Admin Functions
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Authorise a consensus engine address to write decisions.
     *         Call this after deploying each consensus engine instance.
     */
    function authorizeRecorder(address recorder) external onlyAdmin {
        require(recorder != address(0), "GuardMesh: Zero address");
        authorizedRecorders[recorder] = true;
        emit RecorderAuthorized(recorder, block.timestamp);
    }

    /**
     * @notice Revoke a recorder's write access (e.g. compromised key).
     */
    function revokeRecorder(address recorder) external onlyAdmin {
        authorizedRecorders[recorder] = false;
        emit RecorderRevoked(recorder, block.timestamp);
    }

    /**
     * @notice Transfer admin rights to a new address.
     */
    function transferAdmin(address newAdmin) external onlyAdmin {
        require(newAdmin != address(0), "GuardMesh: Zero address");
        emit AdminTransferred(admin, newAdmin);
        admin = newAdmin;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Core Write Function
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Anchor a GuardMesh decision on-chain.
     *         Only callable by an authorised consensus engine.
     *
     * @param agentId           The agent that generated the intent
     * @param merkleRoot        Merkle root of the full decision bundle in 0G Storage
     * @param approved          True if the consensus outcome allows the action
     * @param outcome           OUTCOME_APPROVED | BLOCKED | CONTESTED | PENDING
     * @param actionType        What the agent wanted to do ("forum_post", etc.)
     * @param target            Target system or endpoint
     * @param approveCount      Guardian votes in favour (0-3)
     * @param blockCount        Guardian votes against  (0-3)
     * @param blockedReason     Aggregated guardian reason (empty if approved)
     * @param intentTimestamp   Off-chain timestamp of the original intent broadcast
     */
    function recordDecision(
        string  calldata agentId,
        bytes32          merkleRoot,
        bool             approved,
        uint8            outcome,
        string  calldata actionType,
        string  calldata target,
        uint8            approveCount,
        uint8            blockCount,
        string  calldata blockedReason,
        uint256          intentTimestamp
    ) external onlyAuthorized {
        require(merkleRoot != bytes32(0),               "GuardMesh: Invalid merkle root");
        require(_decisions[merkleRoot].recordedAt == 0, "GuardMesh: Decision already recorded");
        require(bytes(agentId).length > 0,              "GuardMesh: Empty agent ID");
        require(approveCount + blockCount <= 3,         "GuardMesh: Vote count exceeds guardian total");
        require(
            outcome == OUTCOME_APPROVED  ||
            outcome == OUTCOME_BLOCKED   ||
            outcome == OUTCOME_CONTESTED ||
            outcome == OUTCOME_PENDING,
            "GuardMesh: Invalid outcome code"
        );

        _decisions[merkleRoot] = Decision({
            agentId:          agentId,
            merkleRoot:       merkleRoot,
            approved:         approved,
            outcome:          outcome,
            actionType:       actionType,
            target:           target,
            approveCount:     approveCount,
            blockCount:       blockCount,
            blockedReason:    blockedReason,
            intentTimestamp:  intentTimestamp,
            recordedAt:       block.timestamp,
            recorder:         msg.sender
        });

        bytes32 agentKey = keccak256(abi.encodePacked(agentId));
        _agentHistory[agentKey].push(merkleRoot);
        _allRoots.push(merkleRoot);

        emit DecisionRecorded(
            agentId,
            merkleRoot,
            approved,
            outcome,
            actionType,
            intentTimestamp,
            msg.sender
        );
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Read Functions
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Retrieve a single decision by its merkle root hash.
     *         This is the primary verification function — any auditor can call this.
     */
    function getDecision(bytes32 merkleRoot)
        external
        view
        returns (Decision memory)
    {
        require(_decisions[merkleRoot].recordedAt != 0, "GuardMesh: Decision not found");
        return _decisions[merkleRoot];
    }

    /**
     * @notice Return the full decision history for a given agent.
     *         WARNING: unbounded — use paginated version for large histories.
     */
    function getAgentHistory(string calldata agentId)
        external
        view
        returns (Decision[] memory history)
    {
        bytes32   agentKey = keccak256(abi.encodePacked(agentId));
        bytes32[] storage roots = _agentHistory[agentKey];

        history = new Decision[](roots.length);
        for (uint256 i = 0; i < roots.length; i++) {
            history[i] = _decisions[roots[i]];
        }
    }

    /**
     * @notice Paginated agent history — use this for the Audit Trail dashboard page.
     * @param agentId  Target agent
     * @param offset   Start index (0-based)
     * @param limit    Max results per page
     * @return page    Slice of Decision structs
     * @return total   Total decisions recorded for this agent
     */
    function getAgentHistoryPaginated(
        string calldata agentId,
        uint256         offset,
        uint256         limit
    ) external view returns (Decision[] memory page, uint256 total) {
        bytes32   agentKey = keccak256(abi.encodePacked(agentId));
        bytes32[] storage roots = _agentHistory[agentKey];
        total = roots.length;

        if (offset >= total) return (new Decision[](0), total);

        uint256 end   = offset + limit > total ? total : offset + limit;
        uint256 count = end - offset;
        page = new Decision[](count);

        for (uint256 i = 0; i < count; i++) {
            page[i] = _decisions[roots[offset + i]];
        }
    }

    /**
     * @notice Paginated global audit trail — for the full Audit Trail dashboard view.
     * @param offset  Start index
     * @param limit   Max results
     * @return page   Slice of Decision structs
     * @return total  Total decisions ever recorded
     */
    function getAllDecisionsPaginated(uint256 offset, uint256 limit)
        external
        view
        returns (Decision[] memory page, uint256 total)
    {
        total = _allRoots.length;
        if (offset >= total) return (new Decision[](0), total);

        uint256 end   = offset + limit > total ? total : offset + limit;
        uint256 count = end - offset;
        page = new Decision[](count);

        for (uint256 i = 0; i < count; i++) {
            page[i] = _decisions[_allRoots[offset + i]];
        }
    }

    /**
     * @notice Check if a decision with this merkle root has been recorded.
     *         Useful for light-weight verification without fetching the full struct.
     */
    function decisionExists(bytes32 merkleRoot) external view returns (bool) {
        return _decisions[merkleRoot].recordedAt != 0;
    }

    /// @notice Total decisions ever anchored on-chain.
    function getTotalDecisions() external view returns (uint256) {
        return _allRoots.length;
    }

    /// @notice Total decisions recorded for a specific agent.
    function getAgentDecisionCount(string calldata agentId)
        external
        view
        returns (uint256)
    {
        return _agentHistory[keccak256(abi.encodePacked(agentId))].length;
    }

    /**
     * @notice Verify that a given merkle root is recorded on-chain and matches
     *         the expected outcome. Used by auditors / compliance tools.
     * @return exists    True if the root is on-chain
     * @return approved  The recorded approval outcome
     * @return outcome   The specific outcome code
     * @return timestamp When the decision was anchored
     */
    function verifyDecision(bytes32 merkleRoot)
        external
        view
        returns (
            bool    exists,
            bool    approved,
            uint8   outcome,
            uint256 timestamp
        )
    {
        Decision storage d = _decisions[merkleRoot];
        if (d.recordedAt == 0) return (false, false, 0, 0);
        return (true, d.approved, d.outcome, d.recordedAt);
    }
}

contracts/GuardMeshRegistry-ENS.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title GuardMeshRegistry with ENS Integration
 * @notice Extends GuardMeshRegistry to link guardian agents with ENS identities.
 *
 * Each guardian agent stores:
 *   - On-chain policy          (inherited from GuardMeshRegistry)
 *   - ENS name                 guardian-X.guardmesh.eth
 *   - ENS namehash node        (computed on-chain via ENSIP-1)
 *   - Cached metadata          role, model, version (read from ENS or set locally)
 *   - Verification timestamp   last time ENS ↔ address was verified
 *
 * ENS resolution starts on Ethereum L1.  On 0G Chain the contract stores
 * the *expected* mapping and emits events so off-chain indexers can
 * cross-validate.
 */

import "./GuardMeshRegistry.sol";

// ─────────────────────────────────────────────────────────────────────────────
// Minimal ENS interfaces (Mainnet L1 — used only when deployed on L1 or
//   via cross-chain read; on 0G the contract stores names locally)
// ─────────────────────────────────────────────────────────────────────────────

interface IENS {
    function resolver(bytes32 node) external view returns (address);
    function owner(bytes32 node) external view returns (address);
}

interface IResolver {
    function text(bytes32 node, string calldata key) external view returns (string memory);
    function addr(bytes32 node) external view returns (address);
}

contract GuardMeshRegistryENS is GuardMeshRegistry {

    // ─────────────────────────────────────────────────────────────────────────
    // Constants
    // ─────────────────────────────────────────────────────────────────────────

    /// @notice ENS Registry on Ethereum Mainnet (same on Sepolia)
    address public constant ENS_REGISTRY = 0x00000000000C2E074eC69A0dFb2997BA6C7d2e1e;

    // ─────────────────────────────────────────────────────────────────────────
    // ENS Identity Storage
    // ─────────────────────────────────────────────────────────────────────────

    struct ENSIdentity {
        string   ensName;          // e.g. "guardian-1.guardmesh.eth"
        bytes32  ensNode;          // namehash of the full name
        address  resolvedAddress;  // cached resolved address
        uint256  verifiedAt;       // block.timestamp of last verification
        string   role;             // cached guardian.role
        string   model;            // cached guardian.model
        string   version;          // cached guardian.version
    }

    /// agentKey → ENS identity
    mapping(bytes32 => ENSIdentity) private _ensIdentities;

    /// ensNode → agentKey  (reverse lookup)
    mapping(bytes32 => bytes32) public ensNodeToAgent;

    /// All agent keys that have ENS names (for enumeration)
    bytes32[] private _ensAgentKeys;

    // ─────────────────────────────────────────────────────────────────────────
    // Events
    // ─────────────────────────────────────────────────────────────────────────

    event AgentENSAssigned(
        string  indexed agentId,
        string          ensName,
        bytes32         ensNode,
        address indexed resolvedAddress
    );

    event AgentENSVerified(
        string  indexed agentId,
        string          ensName,
        address         resolvedAddress,
        bool            matches
    );

    event AgentENSMetadataUpdated(
        string  indexed agentId,
        string          key,
        string          value
    );

    event AgentENSRevoked(
        string  indexed agentId,
        string          ensName,
        bytes32         ensNode
    );

    // ─────────────────────────────────────────────────────────────────────────
    // On-chain namehash  (ENSIP-1 / EIP-137)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Compute the namehash for a dot-separated ENS name.
     *
     *   namehash("")                = bytes32(0)
     *   namehash("eth")             = keccak256(namehash("") ++ keccak256("eth"))
     *   namehash("guardmesh.eth")   = keccak256(namehash("eth") ++ keccak256("guardmesh"))
     */
    function computeNamehash(string memory ensName)
        public
        pure
        returns (bytes32 node)
    {
        node = bytes32(0);
        if (bytes(ensName).length == 0) return node;

        // Split on "." and process right-to-left
        bytes memory nameBytes = bytes(ensName);
        uint256 labelStart = nameBytes.length;

        // Walk backwards through the string
        for (uint256 i = nameBytes.length; i > 0; i--) {
            if (nameBytes[i - 1] == 0x2E || i == 1) {
                // Extract label
                uint256 start = (nameBytes[i - 1] == 0x2E) ? i : i - 1;
                uint256 len = labelStart - start;

                bytes memory label = new bytes(len);
                for (uint256 j = 0; j < len; j++) {
                    label[j] = nameBytes[start + j];
                }

                bytes32 labelHash = keccak256(label);
                node = keccak256(abi.encodePacked(node, labelHash));
                labelStart = i - 1;
            }
        }
    }

    /**
     * @notice Convenience: compute namehash for a guardian subname.
     * @param label  e.g. "guardian-1"
     * @param parent e.g. "guardmesh.eth"
     */
    function computeSubnameHash(string memory label, string memory parent)
        public
        pure
        returns (bytes32)
    {
        bytes32 parentNode = computeNamehash(parent);
        bytes32 labelHash  = keccak256(bytes(label));
        return keccak256(abi.encodePacked(parentNode, labelHash));
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Registration with ENS
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Register agent with full ENS identity.
     *         Calls parent registerAgent() then links ENS name.
     */
    function registerAgentWithENS(
        string calldata agentId,
        string calldata ensName,
        address         resolvedAddress,
        string calldata roleScope,
        string[] calldata allowedActions,
        string calldata ensRole,
        string calldata ensModel,
        string calldata ensVersion
    ) external returns (bytes32) {
        // 1. Register base policy (external call, returns void)
        this.registerAgent(agentId, roleScope, allowedActions);

        // 2. Compute policy key
        bytes32 policyKey = _key(agentId);

        // 3. Compute and store ENS identity
        bytes32 ensNode = computeNamehash(ensName);

        _ensIdentities[policyKey] = ENSIdentity({
            ensName:         ensName,
            ensNode:         ensNode,
            resolvedAddress: resolvedAddress,
            verifiedAt:      block.timestamp,
            role:            ensRole,
            model:           ensModel,
            version:         ensVersion
        });

        ensNodeToAgent[ensNode] = policyKey;
        _ensAgentKeys.push(policyKey);

        emit AgentENSAssigned(agentId, ensName, ensNode, resolvedAddress);
        return policyKey;
    }

    /**
     * @notice Assign ENS name to an already-registered agent.
     */
    function assignENSName(
        string calldata agentId,
        string calldata ensName,
        address         resolvedAddress
    ) external onlyAgentOwner(agentId) {
        bytes32 key = _key(agentId);
        bytes32 ensNode = computeNamehash(ensName);

        // Clear old reverse mapping if exists
        bytes32 oldNode = _ensIdentities[key].ensNode;
        if (oldNode != bytes32(0)) {
            delete ensNodeToAgent[oldNode];
        }

        _ensIdentities[key].ensName         = ensName;
        _ensIdentities[key].ensNode         = ensNode;
        _ensIdentities[key].resolvedAddress = resolvedAddress;
        _ensIdentities[key].verifiedAt      = block.timestamp;

        ensNodeToAgent[ensNode] = key;

        // Track in list if not already tracked
        bool found = false;
        for (uint256 i = 0; i < _ensAgentKeys.length; i++) {
            if (_ensAgentKeys[i] == key) { found = true; break; }
        }
        if (!found) _ensAgentKeys.push(key);

        emit AgentENSAssigned(agentId, ensName, ensNode, resolvedAddress);
    }

    /**
     * @notice Revoke ENS association from an agent.
     */
    function revokeENSName(string calldata agentId)
        external
        onlyAgentOwner(agentId)
    {
        bytes32 key = _key(agentId);
        ENSIdentity storage eid = _ensIdentities[key];
        require(bytes(eid.ensName).length > 0, "GuardMesh: No ENS name");

        emit AgentENSRevoked(agentId, eid.ensName, eid.ensNode);

        delete ensNodeToAgent[eid.ensNode];
        delete _ensIdentities[key];
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Metadata (cached on-chain)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Update cached ENS metadata for an agent.
     */
    function updateENSMetadata(
        string calldata agentId,
        string calldata role,
        string calldata model,
        string calldata version
    ) external onlyAgentOwner(agentId) {
        bytes32 key = _key(agentId);
        ENSIdentity storage eid = _ensIdentities[key];
        require(bytes(eid.ensName).length > 0, "GuardMesh: No ENS name");

        if (bytes(role).length > 0)    eid.role    = role;
        if (bytes(model).length > 0)   eid.model   = model;
        if (bytes(version).length > 0) eid.version = version;

        emit AgentENSMetadataUpdated(agentId, "guardian.role",    role);
        emit AgentENSMetadataUpdated(agentId, "guardian.model",   model);
        emit AgentENSMetadataUpdated(agentId, "guardian.version", version);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Read Functions
    // ─────────────────────────────────────────────────────────────────────────

    function getAgentENSName(string calldata agentId)
        external view returns (string memory)
    {
        return _ensIdentities[_key(agentId)].ensName;
    }

    function getAgentENSIdentity(string calldata agentId)
        external view returns (ENSIdentity memory)
    {
        return _ensIdentities[_key(agentId)];
    }

    function getAgentByENSNode(bytes32 ensNode)
        external view returns (string memory agentId)
    {
        bytes32 key = ensNodeToAgent[ensNode];
        require(key != bytes32(0), "GuardMesh: ENS node not linked");
        return _ensIdentities[key].ensName;
    }

    /**
     * @notice Verify that the stored resolved address matches expected.
     */
    function verifyAgentENS(
        string calldata agentId,
        address expectedAddress
    ) external view returns (bool) {
        bytes32 key = _key(agentId);
        ENSIdentity storage eid = _ensIdentities[key];
        if (bytes(eid.ensName).length == 0) return false;
        return eid.resolvedAddress == expectedAddress;
    }

    /**
     * @notice Return count of agents with ENS names.
     */
    function getENSAgentCount() external view returns (uint256) {
        return _ensAgentKeys.length;
    }

    /**
     * @notice Paginated list of ENS-enabled agents.
     */
    function getENSAgentsPaginated(uint256 offset, uint256 limit)
        external view
        returns (ENSIdentity[] memory page, uint256 total)
    {
        total = _ensAgentKeys.length;
        if (offset >= total) return (new ENSIdentity[](0), total);

        uint256 end   = offset + limit > total ? total : offset + limit;
        uint256 count = end - offset;
        page = new ENSIdentity[](count);

        for (uint256 i = 0; i < count; i++) {
            page[i] = _ensIdentities[_ensAgentKeys[offset + i]];
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // L1 ENS verification (only works when deployed on Mainnet / fork)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Query ENS Registry on-chain and verify resolution.
     *         Only functional on Ethereum L1 or a fork.
     */
    function verifyAgentViaENSOnchain(
        string calldata agentId,
        address expectedAddress
    ) external view returns (bool) {
        bytes32 key = _key(agentId);
        ENSIdentity storage eid = _ensIdentities[key];
        if (bytes(eid.ensName).length == 0) return false;

        try IENS(ENS_REGISTRY).resolver(eid.ensNode) returns (address rAddr) {
            if (rAddr == address(0)) return false;
            try IResolver(rAddr).addr(eid.ensNode) returns (address resolved) {
                return resolved == expectedAddress;
            } catch {
                return false;
            }
        } catch {
            return false;
        }
    }

    /**
     * @notice Read a text record from ENS (L1 only).
     */
    function readENSTextRecord(
        string calldata agentId,
        string calldata key
    ) external view returns (string memory) {
        bytes32 agentKey = _key(agentId);
        ENSIdentity storage eid = _ensIdentities[agentKey];
        if (bytes(eid.ensName).length == 0) return "";

        try IENS(ENS_REGISTRY).resolver(eid.ensNode) returns (address rAddr) {
            if (rAddr == address(0)) return "";
            try IResolver(rAddr).text(eid.ensNode, key) returns (string memory v) {
                return v;
            } catch { return ""; }
        } catch { return ""; }
    }

    // _key is inherited from GuardMeshRegistry (virtual)
}

contracts/GuardMeshRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title GuardMeshRegistry
 * @notice Agent identity and policy store for the GuardMesh decentralized AI firewall.
 *         Deployed on 0G Chain (EVM-compatible, Cancun-Deneb).
 *
 * @dev Stores per-agent policies: role scope, allowed/denied actions, and
 *      consensus threshold. Guardians query this at runtime via 0G KV Store
 *      or direct on-chain reads. Policies written here are the source of truth
 *      for every guardian evaluation.
 */
contract GuardMeshRegistry {

    // ─────────────────────────────────────────────────────────────────────────
    // Data Structures
    // ─────────────────────────────────────────────────────────────────────────

    /// @dev Consensus threshold options:
    ///      1 = Any 1 guardian approves  → action allowed
    ///      2 = Majority (2/3) approve   → action allowed  (default)
    ///      3 = Unanimous (3/3) approve  → action allowed
    uint8 public constant THRESHOLD_ANY        = 1;
    uint8 public constant THRESHOLD_MAJORITY   = 2;
    uint8 public constant THRESHOLD_UNANIMOUS  = 3;

    struct Policy {
        string   agentId;
        string   roleScope;            // e.g. "code_analysis_only"
        string[] allowedActions;       // e.g. ["read_file", "query_db"]
        string[] deniedActions;        // explicit blocklist e.g. ["forum_post", "change_permissions"]
        string[] allowedDataSources;   // tables/APIs the agent may touch
        uint8    consensusThreshold;   // 1 | 2 | 3
        address  owner;                // wallet that registered this agent
        uint256  registeredAt;         // block.timestamp at registration
        uint256  updatedAt;            // block.timestamp of last policy change
        bool     active;               // false = deactivated / suspended
    }

    // ─────────────────────────────────────────────────────────────────────────
    // State
    // ─────────────────────────────────────────────────────────────────────────

    /// agentId hash  →  Policy
    mapping(bytes32 => Policy) private _policies;

    /// agentId hash  →  exists?
    mapping(bytes32 => bool) private _registered;

    /// owner address →  list of agentId hashes owned
    mapping(address => bytes32[]) private _ownerAgents;

    /// flat list of all registered agentId hashes (for enumeration)
    bytes32[] private _allAgentKeys;

    /// plain agentId hash → agentId string (needed for enumeration)
    mapping(bytes32 => string) private _keyToId;

    // ─────────────────────────────────────────────────────────────────────────
    // Events
    // ─────────────────────────────────────────────────────────────────────────

    event AgentRegistered(
        string  indexed agentId,
        address indexed owner,
        string          roleScope,
        uint256         timestamp
    );

    event PolicyUpdated(
        string  indexed agentId,
        address indexed updatedBy,
        uint256         timestamp
    );

    event AgentDeactivated(
        string  indexed agentId,
        address indexed owner,
        uint256         timestamp
    );

    event AgentReactivated(
        string  indexed agentId,
        address indexed owner,
        uint256         timestamp
    );

    // ─────────────────────────────────────────────────────────────────────────
    // Modifiers
    // ─────────────────────────────────────────────────────────────────────────

    modifier onlyAgentOwner(string memory agentId) {
        bytes32 key = _key(agentId);
        require(_registered[key], "GuardMesh: Agent not registered");
        require(_policies[key].owner == msg.sender, "GuardMesh: Not agent owner");
        _;
    }

    modifier agentExists(string memory agentId) {
        require(_registered[_key(agentId)], "GuardMesh: Agent not registered");
        _;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Write Functions
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Register a new agent with its identity and initial policy.
     * @param agentId        Unique agent identifier (e.g. "eng-assistant-04")
     * @param roleScope      What this agent is allowed to do (e.g. "code_analysis_only")
     * @param allowedActions Initial list of permitted action types
     */
    function registerAgent(
        string calldata   agentId,
        string calldata   roleScope,
        string[] calldata allowedActions
    ) external {
        require(bytes(agentId).length > 0,   "GuardMesh: Empty agent ID");
        require(bytes(roleScope).length > 0,  "GuardMesh: Empty role scope");

        bytes32 key = _key(agentId);
        require(!_registered[key], "GuardMesh: Agent already registered");

        _policies[key] = Policy({
            agentId:            agentId,
            roleScope:          roleScope,
            allowedActions:     allowedActions,
            deniedActions:      new string[](0),
            allowedDataSources: new string[](0),
            consensusThreshold: THRESHOLD_MAJORITY, // safe default
            owner:              msg.sender,
            registeredAt:       block.timestamp,
            updatedAt:          block.timestamp,
            active:             true
        });

        _registered[key]  = true;
        _keyToId[key]     = agentId;
        _allAgentKeys.push(key);
        _ownerAgents[msg.sender].push(key);

        emit AgentRegistered(agentId, msg.sender, roleScope, block.timestamp);
    }

    /**
     * @notice Update an agent's full policy (allowed actions, denied actions,
     *         consensus threshold). Only callable by the agent owner.
     * @param agentId            Target agent
     * @param allowedActions     New allowed action list
     * @param deniedActions      Explicit blocklist (e.g. "forum_post")
     * @param allowedDataSources Tables / APIs this agent may touch
     * @param consensusThreshold 1=Any1 | 2=Majority | 3=Unanimous
     */
    function updatePolicy(
        string    calldata agentId,
        string[]  calldata allowedActions,
        string[]  calldata deniedActions,
        string[]  calldata allowedDataSources,
        uint8              consensusThreshold
    ) external onlyAgentOwner(agentId) {
        require(
            consensusThreshold >= THRESHOLD_ANY &&
            consensusThreshold <= THRESHOLD_UNANIMOUS,
            "GuardMesh: Invalid threshold (1=Any1, 2=Majority, 3=Unanimous)"
        );

        bytes32 key = _key(agentId);
        Policy storage p = _policies[key];

        p.allowedActions     = allowedActions;
        p.deniedActions      = deniedActions;
        p.allowedDataSources = allowedDataSources;
        p.consensusThreshold = consensusThreshold;
        p.updatedAt          = block.timestamp;

        emit PolicyUpdated(agentId, msg.sender, block.timestamp);
    }

    /**
     * @notice Update only the role scope of an agent.
     */
    function updateRoleScope(
        string calldata agentId,
        string calldata roleScope
    ) external onlyAgentOwner(agentId) {
        require(bytes(roleScope).length > 0, "GuardMesh: Empty role scope");
        bytes32 key = _key(agentId);
        _policies[key].roleScope  = roleScope;
        _policies[key].updatedAt  = block.timestamp;
        emit PolicyUpdated(agentId, msg.sender, block.timestamp);
    }

    /**
     * @notice Deactivate an agent — guardians will hard-block all intents.
     */
    function deactivateAgent(string calldata agentId)
        external
        onlyAgentOwner(agentId)
    {
        bytes32 key = _key(agentId);
        _policies[key].active    = false;
        _policies[key].updatedAt = block.timestamp;
        emit AgentDeactivated(agentId, msg.sender, block.timestamp);
    }

    /**
     * @notice Re-activate a previously deactivated agent.
     */
    function reactivateAgent(string calldata agentId)
        external
        onlyAgentOwner(agentId)
    {
        bytes32 key = _key(agentId);
        _policies[key].active    = true;
        _policies[key].updatedAt = block.timestamp;
        emit AgentReactivated(agentId, msg.sender, block.timestamp);
    }

    /**
     * @notice Transfer ownership of an agent's policy to a new address.
     */
    function transferAgentOwnership(
        string  calldata agentId,
        address          newOwner
    ) external onlyAgentOwner(agentId) {
        require(newOwner != address(0), "GuardMesh: Zero address");
        bytes32 key = _key(agentId);
        _policies[key].owner     = newOwner;
        _policies[key].updatedAt = block.timestamp;
        _ownerAgents[newOwner].push(key);
        emit PolicyUpdated(agentId, msg.sender, block.timestamp);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Read Functions
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Get the full policy for an agent. Used by guardians at evaluation time.
     */
    function getPolicy(string calldata agentId)
        external
        view
        agentExists(agentId)
        returns (Policy memory)
    {
        return _policies[_key(agentId)];
    }

    /// @notice Check if an agent is registered.
    function isRegistered(string calldata agentId) external view returns (bool) {
        return _registered[_key(agentId)];
    }

    /// @notice Check if an agent is registered AND active.
    function isActive(string calldata agentId) external view returns (bool) {
        bytes32 key = _key(agentId);
        return _registered[key] && _policies[key].active;
    }

    /// @notice Total number of registered agents.
    function getAgentCount() external view returns (uint256) {
        return _allAgentKeys.length;
    }

    /// @notice Return all agentIds registered by a given owner wallet.
    function getOwnerAgents(address owner)
        external
        view
        returns (string[] memory agentIds)
    {
        bytes32[] storage keys = _ownerAgents[owner];
        agentIds = new string[](keys.length);
        for (uint256 i = 0; i < keys.length; i++) {
            agentIds[i] = _keyToId[keys[i]];
        }
    }

    /**
     * @notice Paginated enumeration of all agents (for dashboard).
     * @param offset  Start index
     * @param limit   Max results to return
     */
    function getAllAgentsPaginated(uint256 offset, uint256 limit)
        external
        view
        returns (Policy[] memory page, uint256 total)
    {
        total = _allAgentKeys.length;
        if (offset >= total) return (new Policy[](0), total);

        uint256 end   = offset + limit > total ? total : offset + limit;
        uint256 count = end - offset;
        page = new Policy[](count);

        for (uint256 i = 0; i < count; i++) {
            page[i] = _policies[_allAgentKeys[offset + i]];
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // Internal Helpers
    // ─────────────────────────────────────────────────────────────────────────

    function _key(string memory agentId) internal pure virtual returns (bytes32) {
        return keccak256(abi.encodePacked(agentId));
    }
}

